    (X'01a16f2992cc75be86fc983b6752f444', 'bullet', 'Led the migration of 12 backend services from Python to Rust.', 'Led the migration of 12 backend services from Python to Rust.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
    (X'01a16f2992cc75be86fc983c67c033c2', 'bullet', 'Cut p99 latency of the routing API from 480 ms to 95 ms.', 'Cut p99 latency of the routing API from 480 ms to 95 ms.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
    (X'01a16f2992cc75be86fc983d50209f14', 'bullet', 'Mentored four junior engineers through their first production launches; two now lead teams of their own.', 'Mentored four junior engineers through their first production launches.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
    (X'01a16f2992cc75be86fc983e98c6466a', 'bullet', 'Migrated 12 backend services from Python to Rust, one service at a time.', 'Migrated 12 backend services from Python to Rust, one service at a time.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
    (X'01a16f2992cc75be86fc983f6ea3871a', 'bullet', 'Designed the event pipeline that processes shipment updates.', 'Designed the event pipeline that processes shipment updates.', X'01a16f2992cc75be86fc9836c70f43dd', 0, 'cleaned', 'A word was split across two lines in the PDF.', NULL, NULL),
    (X'01a16f2992cc75be86fc98403aaea84b', 'bullet', 'Ran the on-call rotation for the routing team and wrote the runbooks that new engineers still start from.', 'Ran the on-call rotation for the routing team and wrote the runbooks that new engineers still start from.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
    (X'01a16f2992cc75be86fc984166f98401', 'bullet', 'Introduced structured logging and distributed tracing across the routing services, so most incidents can now be diagnosed from a single dashboard.', 'Introduced structured logging and distributed tracing across the routing services, so most incidents can now be diagnosed from a single dashboard.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
    (X'01a16f2992cc75be86fc98422c9c7f10', 'bullet', 'Worked with product managers to scope the multi-depot routing project and delivered it across two quarters.', 'Worked with product managers to scope the multi-depot routing project and delivered it across two quarters.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
    (X'01a16f2992cc75be86fc9843d580e18b', 'bullet', 'Built a capacity model for the routing cluster that the infrastructure team now uses for quarterly budgeting.', 'Built a capacity model for the routing cluster that the infrastructure team now uses for quarterly budgeting.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
    (X'01a16f2992cc75be86fc9844f46f7bf1', 'bullet', 'Wrote the internal guide to building Rust services at Northwind, covering error handling, testing and observability.', 'Wrote the internal guide to building Rust services at Northwind, covering error handling, testing and observability.', X'01a16f2992cc75be86fc9836c70f43dd', 0, NULL, NULL, NULL, NULL),
