INSERT INTO job_descriptions (job_id, text) VALUES
    (X'01a16f2992cd7742b64a79d69b6d09ea', 'We''re looking for a senior engineer to own our Rust services, mentor the team and improve reliability.'),
    (X'01a16f2992cd7742b64a7a08ac14ea8f', 'Build and operate the services that move money for thousands of small businesses.'),
    (X'01a16f2992cd7742b64a7a4b93a1c798', 'Lead the technical direction of our routing platform: reliability, observability and the next generation of route planning.'),
    (X'01a16f2992cd7742b64a7a6da729bbd2', 'Write and maintain the Rust services behind our port logistics platform.'),
    (X'01a16f2992cd7742b64a7a8990985703', 'Own the services that pay out sellers on time, every time.'),
    (X'01a16f2992cd7742b64a7aac310b3fe2', 'Build the tracing and metrics platform hundreds of engineers rely on.'),
    (X'01a16f2992cd7742b64a7acdef7ca58e', 'Lead backend work on our energy-trading platform.'),
    (X'01a16f2992cd7742b64a7ae98d4ed8e2', 'Run the infrastructure behind our machine-learning research.'),
    (X'01a16f2992cd7742b64a7aeab9ecf990', 'Help us build the internal platform our product teams deploy on.');
